//! Emits wit/vectors.json from the golden vector table. The hex field is
//! generated by the Rust codec (ground truth for the Lua host codec tests).
//!
//! Usage: cargo run -p crab-sdk --bin gen-vectors [-- <output-path>]

use crab_sdk::codec::encode_to_vec;
use crab_sdk::vectors::vectors;

fn hex(bytes: &[u8]) -> String {
    bytes.iter().map(|b| format!("{b:02x}")).collect()
}

fn json_escape(s: &str) -> String {
    let mut out = String::with_capacity(s.len() + 2);
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            c if (c as u32) < 0x20 => out.push_str(&format!("\\u{:04x}", c as u32)),
            c => out.push(c),
        }
    }
    out
}

fn main() {
    let path = std::env::args()
        .nth(1)
        .unwrap_or_else(|| "wit/vectors.json".to_string());

    let mut out = String::from("[\n");
    let vs = vectors();
    for (i, v) in vs.iter().enumerate() {
        let encoded = hex(&encode_to_vec(&v.value));
        assert_eq!(
            encoded, v.hex,
            "vector '{}': table hex disagrees with codec",
            v.desc
        );
        out.push_str(&format!(
            "  {{\"desc\": \"{}\", \"type\": {}, \"value\": {}, \"hex\": \"{}\"}}{}\n",
            json_escape(v.desc),
            v.type_json,
            v.value_json,
            encoded,
            if i + 1 == vs.len() { "" } else { "," }
        ));
    }
    out.push_str("]\n");

    std::fs::write(&path, out).expect("write vectors.json");
    eprintln!("wrote {} vectors to {path}", vs.len());
}
